with mission_content(number, objective, why_it_matters, concepts, tasks, deliverables, hints, resources, estimated_minutes) as (
  values
    (1, 'Translate the logistics brief into a build plan and run the starter repository.', 'Clear scope prevents a project from becoming a collection of disconnected endpoints.', '["problem framing","repository hygiene","environment variables"]'::jsonb, '["write the actors and core workflows","run the starter test suite","record local setup steps"]'::jsonb, '["one-page project brief","working local setup","setup notes"]'::jsonb, '["Start with actors and state changes.","Write one happy path and two failure paths.","Keep configuration in environment variables."]'::jsonb, '["HTTP semantics","12-factor configuration"]'::jsonb, 45),
    (2, 'Model customers, orders, shipments, and lifecycle transitions before writing routes.', 'A deliberate data model makes ownership and business rules testable.', '["entity relationships","state machines","PostgreSQL"]'::jsonb, '["draw an ERD","define keys and constraints","document status transitions"]'::jsonb, '["ERD","migration plan","trade-off notes"]'::jsonb, '["Identify the source of truth for each status.","Prefer constraints that protect invariants.","Explain one denormalization decision."]'::jsonb, '["relational modeling","database constraints"]'::jsonb, 90),
    (3, 'Add secure identity, password hashing, and ownership checks.', 'Authentication without authorization does not protect customer data.', '["JWT","password hashing","authorization"]'::jsonb, '["implement registration and login","hash passwords","test cross-user access"]'::jsonb, '["auth endpoints","ownership test","security notes"]'::jsonb, '["Hash before storage.","Validate token claims at the boundary.","Test a user attempting to read another user record."]'::jsonb, '["OWASP authentication","JWT claims"]'::jsonb, 120),
    (4, 'Build validated order and shipment REST endpoints.', 'A predictable API is easier to integrate, test, and explain.', '["REST design","validation","service boundaries"]'::jsonb, '["define request and response schemas","implement create/read/update flows","return consistent errors"]'::jsonb, '["documented CRUD endpoints","validation examples","API test evidence"]'::jsonb, '["Keep transport and domain logic separate.","Reject malformed state changes early.","Use stable status codes."]'::jsonb, '["HTTP status codes","Pydantic validation"]'::jsonb, 180),
    (5, 'Make status transitions predictable, idempotent, and defendable.', 'Business rules are where a CRUD demo becomes a real system.', '["domain rules","idempotency","edge cases"]'::jsonb, '["encode allowed transitions","reject invalid moves","handle repeated requests"]'::jsonb, '["transition policy","edge-case tests","idempotency note"]'::jsonb, '["List states before transitions.","Treat invalid transitions as domain errors.","Ask what happens if the same request is retried."]'::jsonb, '["state machines","idempotent APIs"]'::jsonb, 120),
    (6, 'Build unit and integration tests that prove the important behavior.', 'Tests are portfolio evidence of engineering judgment, not just a coverage number.', '["fixtures","API testing","test pyramid"]'::jsonb, '["test domain transitions","test auth boundaries","test a complete order flow"]'::jsonb, '["focused test suite","fixture strategy","coverage notes"]'::jsonb, '["Start with failure cases.","Keep tests independent.","Name tests as behavior statements."]'::jsonb, '["pytest","integration testing"]'::jsonb, 120),
    (7, 'Prepare the service to be observable and resilient.', 'Production concerns reveal whether the design can be operated by another team.', '["logging","health checks","error handling"]'::jsonb, '["add health and readiness checks","standardize errors","define logging fields"]'::jsonb, '["production checklist","health endpoint","error contract"]'::jsonb, '["Never log secrets.","Separate client-safe errors from diagnostics.","Define what a failed dependency looks like."]'::jsonb, '["structured logging","service health"]'::jsonb, 90),
    (8, 'Package the API and database for repeatable local setup.', 'Reproducible environments reduce onboarding friction and hidden assumptions.', '["containers","compose","configuration"]'::jsonb, '["write a Dockerfile","configure Compose","document persistent volumes"]'::jsonb, '["Dockerfile","Compose setup","run instructions"]'::jsonb, '["Keep images small and deterministic.","Inject secrets at runtime.","Verify the clean checkout path."]'::jsonb, '["Docker Compose","container networking"]'::jsonb, 90),
    (9, 'Create a credible deployment plan with secrets and rollback thinking.', 'A deployment plan demonstrates responsible delivery without claiming production usage.', '["cloud basics","secrets","rollbacks"]'::jsonb, '["choose a deployment target","map configuration","write rollback steps"]'::jsonb, '["architecture diagram","deployment runbook","risk list"]'::jsonb, '["Separate build and runtime configuration.","Name the migration order.","Include a rollback trigger."]'::jsonb, '["deployment strategies","secret management"]'::jsonb, 90),
    (10, 'Make the project easy for another engineer to run and review.', 'Good documentation turns implementation work into shareable evidence.', '["README","API docs","decision records"]'::jsonb, '["write setup instructions","add example requests","record major decisions"]'::jsonb, '["polished README","API examples","decision record"]'::jsonb, '["Test every command in the README.","Explain trade-offs, not only choices.","Show a successful request and failure."]'::jsonb, '["OpenAPI","technical writing"]'::jsonb, 60),
    (11, 'Audit the project against the rubric and close the highest-value gaps.', 'A structured review converts feedback into measurable improvement.', '["rubrics","self-review","scope"]'::jsonb, '["score each rubric criterion","select three improvements","capture before/after evidence"]'::jsonb, '["review log","improvement diff","final evidence index"]'::jsonb, '["Prioritize correctness and security.","Use evidence links, not adjectives.","Keep scope changes explicit."]'::jsonb, '["code review","engineering rubrics"]'::jsonb, 60),
    (12, 'Practice explaining decisions, failures, and next steps in a technical viva.', 'Explaining trade-offs shows understanding beyond copying an implementation.', '["technical storytelling","trade-offs","reflection"]'::jsonb, '["answer ten project questions","explain one failure","describe the next iteration"]'::jsonb, '["viva answer bank","one-minute project explanation","reflection"]'::jsonb, '["Answer with context, decision, and consequence.","Admit limitations clearly.","Connect each answer to evidence in the project."]'::jsonb, '["STAR storytelling","technical interviews"]'::jsonb, 60)
)
update public.project_missions m
set definition = m.definition
  || jsonb_build_object(
    'objective', c.objective,
    'why', c.why_it_matters,
    'concepts', c.concepts,
    'tasks', c.tasks,
    'deliverables', c.deliverables,
    'hints', c.hints,
    'resources', c.resources,
    'estimatedMinutes', c.estimated_minutes
  )
from mission_content c
where m.variant_id = '00000000-0000-0000-0002-000000000001'
  and m.mission_number = c.number;
